import{_ as o,o as t,c as a,a3 as n}from"./chunks/framework.C6R8kWFE.js";const m=JSON.parse('{"title":"Files & formats","description":"","frontmatter":{},"headers":[],"relativePath":"guide/files.md","filePath":"guide/files.md"}'),d={name:"guide/files.md"};function s(r,e,i,l,h,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="files-formats" tabindex="-1">Files &amp; formats <a class="header-anchor" href="#files-formats" aria-label="Permalink to &quot;Files &amp; formats&quot;">​</a></h1><p>Your writing lives in plain markdown files that any editor can read, today and in twenty years. When a piece goes out into the world, Blank hands it over as a finely typeset PDF or as a Word document. And when someone sends you a Word document, Blank opens that too.</p><h2 id="formats" tabindex="-1">Which format for what <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Which format for what {#formats}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Open</th><th>Save or export</th><th>Best for</th></tr></thead><tbody><tr><td>Markdown (.md)</td><td><code>Mod</code> <code>O</code></td><td><code>Mod</code> <code>S</code></td><td>your own writing</td></tr><tr><td>PDF</td><td></td><td><code>Mod</code> <code>Alt</code> <code>P</code></td><td>reading and printing</td></tr><tr><td>Word (.docx)</td><td><code>Mod</code> <code>O</code></td><td><code>Mod</code> <code>Alt</code> <code>W</code></td><td>people who use Word</td></tr></tbody></table><p><code>Mod</code> is <code>Cmd</code> on macOS and <code>Ctrl</code> on Windows and Linux.</p><h2 id="markdown" tabindex="-1">Your documents: markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Your documents: markdown {#markdown}&quot;">​</a></h2><p>Everything you write is kept as markdown: plain text with a few marks like <code>#</code> for headings, so the file stays small, readable and yours.</p><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>New file</td><td><code>Mod</code> <code>N</code></td></tr><tr><td>Open</td><td><code>Mod</code> <code>O</code></td></tr><tr><td>Save</td><td><code>Mod</code> <code>S</code></td></tr><tr><td>Save as</td><td><code>Mod</code> <code>Shift</code> <code>S</code></td></tr></tbody></table><p>The open dialog shows your markdown files and Word documents together. Closed Blank without saving? It keeps your text anyway, see <a href="./writing#blank-remembers-your-document">Blank remembers your document</a>.</p><h3 id="frontmatter" tabindex="-1">Properties on top of the file <a class="header-anchor" href="#frontmatter" aria-label="Permalink to &quot;Properties on top of the file {#frontmatter}&quot;">​</a></h3><p>Notes from Obsidian, pandoc or a static site generator often start with a few properties between two <code>---</code> lines, called frontmatter:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">title: The Lighthouse</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">author: Ada Lovelace</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tags: [sea, light]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Chapter 1</span></span></code></pre></div><p>Blank keeps this block exactly as it is, down to the comments and spacing, and saves it back unchanged. Instead of the raw lines, a quiet line above your text sums it up: <em>The Lighthouse · by Ada Lovelace · tags</em>.</p><p>The <code>title</code> and <code>author</code> also go into your PDF and Word documents, where readers and search show them. Without a <code>title</code>, Blank uses your first heading.</p><h2 id="pdf" tabindex="-1">Share a PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;Share a PDF {#pdf}&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>P</code> and choose where to put the PDF. Blank suggests your document&#39;s name with <code>.pdf</code>.</p><p>The PDF is typeset with care, in the same font, sizes and spacing as the editor:</p><ul><li>set in IBM Plex Sans on the paper of your region, or the <a href="./pages">page setup</a> you chose, and code in IBM Plex Mono,</li><li>every line and every page ends exactly where it ends on your screen,</li><li>a heading never ends a page on its own; it moves to the next page with its text,</li><li><a href="./pages#page-breaks">page breaks</a> start a new page, and horizontal lines are drawn across the text,</li><li>your <a href="./pages#headers-and-footers">page numbers, header and footer</a> are on every page,</li><li>quotes keep their bar on the left and everything inside them,</li><li>line breaks you made with <code>Shift</code> <code>Enter</code> stay, and a numbered list that starts at 3 starts at 3,</li><li><a href="./tables#export">tables</a> look like in the editor, repeat their header row on every page, and keep their rows whole; a row too tall for a page goes on over the next,</li><li>links stay clickable,</li><li>emoji are black and white, in the colour of your text,</li><li>Chinese, Japanese, Korean and other scripts come from the fonts your computer has for them, so a PDF of such text can look a little different when it&#39;s made on another computer.</li></ul><p>Every PDF is a PDF/A, the standard for archiving: it holds its fonts, colours and metadata, so it opens the same in years to come, and theses, offices and courts that ask for PDF/A accept it. It&#39;s also tagged, so screen readers read it in order, in your document&#39;s language, and its headings are bookmarks. If a document can&#39;t be a PDF/A, for example because it uses a character no font has, Blank makes a normal PDF and tells you why.</p><p>If you made PDFs with Blank 2.1 or earlier, lines may now break in other places: the PDF is typeset by Blank itself now, the same way as your screen.</p><p>Images come along at the size they have in Blank, up to the width of the page. Images from the web are downloaded for the PDF, so that needs an internet connection. If an image can&#39;t be loaded, the PDF shows its description in its place, and Blank tells you which one it was.</p><h2 id="word" tabindex="-1">Word documents <a class="header-anchor" href="#word" aria-label="Permalink to &quot;Word documents {#word}&quot;">​</a></h2><h3 id="send-word" tabindex="-1">Send a Word document <a class="header-anchor" href="#send-word" aria-label="Permalink to &quot;Send a Word document {#send-word}&quot;">​</a></h3><p>When someone needs your text in Word, press <code>Mod</code> <code>Alt</code> <code>W</code>. Blank suggests your document&#39;s name with <code>.docx</code>.</p><p>The Word document looks like your PDF, and stays easy to edit: headings, quotes and code use real Word styles, so they show up in Word&#39;s style gallery, navigation pane and table of contents. Lists keep their numbers, links and images come along, and headers, footers and page numbers are Word&#39;s own, so they stay right however the document grows. Tables become real Word tables, with their header row repeated on every page, merged cells and their caption in Word&#39;s caption style. Blank&#39;s fonts are embedded, IBM Plex Sans for the text and IBM Plex Mono for code, so Word shows them even on computers that don&#39;t have them installed. LibreOffice and Google Docs use similar fonts instead.</p><p>Your markdown file stays exactly as it is. The document&#39;s title and author come along, and so do the <a href="#frontmatter">properties</a> at the top of your file: open the Word document in Blank again and they&#39;re back, including the ones Word has no place for. If someone changed the title or author in Word, you get their version.</p><h3 id="open-word-documents" tabindex="-1">Open a Word document <a class="header-anchor" href="#open-word-documents" aria-label="Permalink to &quot;Open a Word document {#open-word-documents}&quot;">​</a></h3><p>Open a Word document like any other file: with <code>Mod</code> <code>O</code>, by starting Blank with it (<code>blank report.docx</code>), or with <strong>Open With → Blank</strong> in your file manager (see <a href="./install">Install</a>). Blank also opens .docm, .dotx and .dotm files, up to 50 MB.</p><p>Blank turns the document into a new, untitled markdown document, and the top of the window shows <em>report.docx (imported)</em>. Press <code>Mod</code> <code>S</code> to keep it: Blank suggests <code>report.md</code>, right next to the original.</p><div class="tip custom-block"><p class="custom-block-title">Your Word file stays untouched</p><p>Blank never writes to the Word document you opened. It won&#39;t even save markdown over a .docx or .pdf if you pick one in the save dialog.</p></div><h3 id="what-comes-along" tabindex="-1">What comes along <a class="header-anchor" href="#what-comes-along" aria-label="Permalink to &quot;What comes along {#what-comes-along}&quot;">​</a></h3><p>Headings, bold and italic text, links, lists, quotes, code, line breaks, page breaks, images and tables make it into your document, and so do the header, the footer and the page numbers. Tables keep their merged cells, header rows and header columns, and their caption. A table without a header row gets its first row as the header, since a markdown table needs one. Images are stored inside the markdown file, so it stays a single file you can move and send; large pictures are scaled down to a size that still prints well.</p><p>Word can do more than markdown, so a few things change on the way:</p><ul><li>a table inside a table cell becomes text, one line per row with the cells separated by <code>|</code>,</li><li>the alignment of table columns is left out,</li><li>footnotes move to the end of the document,</li><li>comments, underlining and colours are left out,</li><li>tracked changes count as accepted,</li><li>charts and drawings Blank can&#39;t show are replaced by their description,</li><li>numbered lists start at 1.</li></ul><div class="tip custom-block"><p class="custom-block-title">Nothing gets lost unnoticed</p><p>Right after opening, Blank tells you what changed, for example <em>1 table inside a table became text</em> or <em>2 comments left out</em>.</p></div><h3 id="back-and-forth" tabindex="-1">Back and forth with Word users <a class="header-anchor" href="#back-and-forth" aria-label="Permalink to &quot;Back and forth with Word users {#back-and-forth}&quot;">​</a></h3><p>A colleague sends you a Word document to work on:</p><ol><li>Open it with <code>Mod</code> <code>O</code>.</li><li>Write, and keep your version with <code>Mod</code> <code>S</code>, as markdown.</li><li>Send it back with <code>Mod</code> <code>Alt</code> <code>W</code>.</li></ol><p>On their side, headings, quotes, lists, links, images and tables arrive as they know them from Word. When they send it back, only the alignment of table columns needs setting again.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know {#good-to-know}&quot;">​</a></h2><p><strong>File names.</strong> On Linux, the save dialog doesn&#39;t add the extension for you. The name Blank suggests already has it, and an export refuses a name with another extension, such as an existing <code>.md</code> file, instead of overwriting it.</p><p><strong>Other formats.</strong> Blank can&#39;t open .doc, .odt, .rtf or .pages files. Save them as .docx in the app they come from, then open that.</p><p><strong>Password-protected documents.</strong> Blank can&#39;t open a Word document that is protected with a password. Remove the password in Word, or ask for an unprotected copy.</p>`,43)])])}const u=o(d,[["render",s]]);export{m as __pageData,u as default};
